  const [form, setForm] = useState<any>({ templateCode: 'ENC-FLAT', costingVariant: 'FLAT_BEADING', surfaceType: 'INDOOR', collarAreaMm2: '', collarThicknessMm: '', glandPlateAreaMm2: '', benchAreaMm2: '', ribWidthMm: '130', dickyBeadingCostLkr: '0', widthMm: 600, heightMm: 1000, depthMm: 200, materialId: '', thicknessMm: '1.0', sheetSpecId: '', doorMaterialId: '', doorThicknessMm: '', mountingPlateMaterialId: '', mountingPlateThicknessMm: '', glandPlateMaterialId: '', glandPlateThicknessMm: '', ribMaterialId: '', ribThicknessMm: '', coverPlateMaterialId: '', coverPlateThicknessMm: '', costPolicyId: '', finishCodes: ['POWDER_COAT_TEXTURE'], hardwareItems: {}, marginPct: '', labourCost: '0', transportCost: '0', otherCost: '0', includeDoor: true, includeMountingPlate: true, includeCoverPlate: true, includeRib: true, includeGlandPlate: true, includeZBracket: false, includeEarthBracket: false, includeBench: false, includeInnerDoor: false, includeCanopy: false, includeMountingBase: false, includeMountingEars: false });
  const [result, setResult] = useState<any>(null); const [busy, setBusy] = useState(false); const [saveBusy, setSaveBusy] = useState(false); const [savedRecord, setSavedRecord] = useState<any>(null); const [error, setError] = useState(''); const [priceDate, setPriceDate] = useState(today()); const [showAdvanced, setShowAdvanced] = useState(false); const [showHardware, setShowHardware] = useState(false);
